#!/usr/bin/env python3
"""Plot ngspice outputs generated by the final RRI simulation decks."""
from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np

root = Path(__file__).resolve().parents[1]
results = root / "results"

cm = np.loadtxt(results / "common_mode_handover.dat", comments="#")
fig, ax = plt.subplots(figsize=(7, 4.2))
ax.plot(cm[:, 0], 1e6 * cm[:, 2], label="NMOS tail XMNT")
ax.plot(cm[:, 0], 1e6 * cm[:, 3], label="PMOS tail XMPT")
ax.plot(cm[:, 0], 1e6 * (cm[:, 4] + cm[:, 6]), label="NMOS pair sum")
ax.plot(cm[:, 0], 1e6 * (cm[:, 5] + cm[:, 7]), label="PMOS pair sum")
ax.set(xlabel="Input common mode (V)", ylabel="Tail current (µA)", title="Complementary input-pair handover")
ax.grid(True, alpha=0.3)
ax.legend()
fig.tight_layout()
fig.savefig(results / "common_mode_handover.png", dpi=180)
plt.close(fig)

tran = np.loadtxt(results / "transient_step.dat")
fig, ax = plt.subplots(figsize=(7, 4.2))
ax.plot(1e6 * tran[:, 0], tran[:, 1], label="Input")
ax.plot(1e6 * tran[:, 0], tran[:, 2], label="Output")
ax.set(xlabel="Time (µs)", ylabel="Voltage (V)", title="Unity-follower 100 mV step, CL = 2 pF")
ax.grid(True, alpha=0.3)
ax.legend()
fig.tight_layout()
fig.savefig(results / "transient_step.png", dpi=180)
plt.close(fig)

ac = np.loadtxt(results / "ac_loopgain_vcm065.dat")
fig, ax_gain = plt.subplots(figsize=(7, 4.2))
ax_phase = ax_gain.twinx()
ax_gain.semilogx(ac[:, 0], ac[:, 1], color="tab:blue", label="Loop-gain magnitude")
ax_phase.semilogx(ac[:, 0], ac[:, 2], color="tab:orange", label="Loop-gain phase")
ax_gain.axhline(0, color="tab:blue", lw=0.8, ls="--")
ax_gain.set(xlabel="Frequency (Hz)", ylabel="Magnitude (dB)", title="Series-injection loop gain, VCM = 0.65 V")
ax_phase.set_ylabel("Continuous phase (degrees)")
ax_gain.grid(True, which="both", alpha=0.3)
handles = ax_gain.get_lines()[:1] + ax_phase.get_lines()[:1]
ax_gain.legend(handles, [h.get_label() for h in handles], loc="best")
fig.tight_layout()
fig.savefig(results / "loopgain_vcm065.png", dpi=180)
plt.close(fig)

swing = np.loadtxt(results / "output_swing.dat")
fig, ax = plt.subplots(figsize=(7, 4.2))
ax.plot(swing[:, 0], swing[:, 1], label="Output")
ax.plot(swing[:, 0], swing[:, 0], ls="--", color="gray", label="Ideal follower")
ax.axvspan(0.45, 0.85, color="tab:green", alpha=0.12, label="Required input range")
ax.set(xlabel="Input voltage (V)", ylabel="Output voltage (V)", title="Unity-follower DC transfer, CL = 2 pF")
ax.grid(True, alpha=0.3)
ax.legend()
fig.tight_layout()
fig.savefig(results / "output_swing.png", dpi=180)
plt.close(fig)
